do $do$
declare p jsonb := $pl$[{"k":"APBIO-MCQ-101","t":"Structure of Water and Hydrogen Bonding","s":"During a sunny afternoon, a pond absorbs substantial heat, but its water temperature rises only slightly. This helps maintain a stable environment for aquatic organisms. Which explanation best accounts for the small temperature change?","a":"D","c":[["A","Heat breaks the covalent bonds within water molecules, giving water a high specific heat capacity.",false,"Bond-type confusion: This explanation mistakes covalent bonds within water molecules for hydrogen bonds between molecules. Ordinary pond warming does not break water's O–H covalent bonds. Fix: Locate each bond within a molecule or between molecules before explaining heat absorption."],["B","Water is nonpolar, so its molecules lack attractions to one another and absorb heat with little temperature change.",false,"Polarity misconception: Water is polar, and its partial charges enable hydrogen bonds between molecules. These attractions, not their absence, contribute to water's resistance to temperature change. Fix: Check whether water's oxygen and hydrogen regions have equal or unequal charge distributions."],["C","Water has a low specific heat capacity, so absorbing substantial heat produces only a small temperature increase.",false,"Specific-heat reversal: A low specific heat capacity means less energy is needed for a given temperature increase. The pond's small temperature increase despite substantial heat absorption indicates high specific heat capacity. Fix: Ask whether a small temperature increase requires little or much energy per unit mass."],["D","Water's polarity allows hydrogen bonds to form between molecules, and disrupting these interactions absorbs energy, giving water a high specific heat capacity.",true,"Water's partial charges allow hydrogen bonding between molecules. Much of the absorbed energy disrupts these interactions rather than increasing molecular motion, so water's temperature changes relatively little, stabilizing the organisms' environment."]]},{"k":"APBIO-MCQ-SV-101-v1","t":"Structure of Water and Hydrogen Bonding","s":"A runner's working muscles release heat into surrounding tissues. The tissues' high water content helps prevent a rapid temperature increase. Which explanation links water's molecular structure to this temperature stability?","a":"A","c":[["A","Water's uneven charge distribution enables hydrogen bonding between molecules; disrupting these attractions requires energy, resulting in a high specific heat capacity.",true,"Polar water molecules form hydrogen bonds with one another. Some incoming heat disrupts these attractions rather than increasing molecular motion, so substantial energy is needed to raise water's temperature. This helps water-rich tissues resist rapid warming."],["B","Water absorbs heat by breaking the covalent bonds connecting oxygen and hydrogen within its molecules, resulting in a high specific heat capacity.",false,"Bond-type confusion: This explanation assigns heat absorption to bonds inside individual water molecules instead of attractions between molecules. Normal tissue warming does not split water's O–H covalent bonds. Fix: Identify whether the relevant bonds connect separate molecules or atoms within one molecule."],["C","Water's nonpolar structure prevents attractions between its molecules, allowing tissues to absorb heat without warming rapidly.",false,"Polarity misconception: Water has an uneven charge distribution that permits hydrogen bonding between molecules. These intermolecular attractions help explain its high specific heat capacity; an absence of attractions does not. Fix: Mark water's partially positive and partially negative regions before predicting intermolecular attractions."],["D","Water's low specific heat capacity means that a large heat input produces only a small temperature increase in tissues.",false,"Specific-heat reversal: Low specific heat capacity would allow a given heat input to produce a larger temperature increase for the same mass. Resistance to warming instead reflects high specific heat capacity. Fix: Compare temperature increases for equal masses receiving equal heat inputs."]]},{"k":"APBIO-MCQ-SV-101-v2","t":"Structure of Water and Hydrogen Bonding","s":"A greenhouse gardener places sealed containers of water beside young tomato plants. As a heater warms the greenhouse, the water absorbs considerable energy but warms slowly, helping buffer temperature changes around the plants. Which explanation connects this effect to water's molecular structure?","a":"C","c":[["A","Water absorbs energy by breaking the covalent bonds joining oxygen and hydrogen within its molecules, resulting in a high specific heat capacity.",false,"Bond-type confusion: This explanation substitutes bonds inside each molecule for attractions between separate molecules. Warming greenhouse water does not split its O–H covalent bonds. Fix: Identify whether the affected bonds connect atoms within water molecules or connect separate molecules."],["B","Water's equal charge distribution makes it nonpolar, so the absence of attractions between molecules allows substantial heat absorption with little warming.",false,"Polarity misconception: Water has an uneven charge distribution that supports hydrogen bonding. Its resistance to warming depends partly on these intermolecular attractions, not on a lack of attraction. Fix: Mark the partially negative oxygen region and partially positive hydrogen regions before predicting molecular attractions."],["C","Water's uneven charge distribution permits hydrogen bonding between molecules; disrupting these attractions requires energy, resulting in a high specific heat capacity.",true,"Polar water molecules attract one another through hydrogen bonds. Energy absorbed during warming partly disrupts these attractions, so substantial heat input produces relatively little temperature change and helps stabilize conditions around the seedlings."],["D","Water requires little energy per gram for each degree of warming, so its low specific heat capacity buffers temperature changes.",false,"Specific-heat reversal: Requiring little energy per degree would cause a larger temperature increase for the same heat input per gram. Slow warming despite substantial energy absorption instead indicates high specific heat capacity. Fix: Compare temperature increases for equal heat inputs per gram before identifying high or low specific heat."]]},{"k":"APBIO-MCQ-SV-101-v3","t":"Structure of Water and Hydrogen Bonding","s":"A biology class grows yeast cultures in tubes surrounded by a water bath. As a heater supplies substantial energy, the bath’s temperature increases only slightly, helping keep the yeast’s environment stable. Which explanation connects this effect to water’s molecular structure?","a":"A","c":[["A","Water’s uneven charge distribution enables hydrogen bonding between molecules; disrupting these attractions takes energy, contributing to a high specific heat capacity.",true,"Water’s partially charged regions attract neighboring water molecules through hydrogen bonds. Some incoming energy disrupts these attractions rather than increasing molecular motion, so considerable energy produces relatively little warming and helps stabilize the cultures’ temperature."],["B","Energy from the heater breaks covalent O–H bonds inside water molecules, contributing to a high specific heat capacity.",false,"Bond-type confusion: This explanation substitutes bonds inside each molecule for attractions between neighboring molecules. Heating the bath under these conditions does not split water’s covalent O–H bonds. Fix: Identify whether the affected bonds connect separate molecules or atoms within one molecule."],["C","Water has no polar regions, so the absence of attractions between its molecules allows substantial energy absorption with little warming.",false,"Polarity misconception: Uneven charge distribution makes water polar and enables intermolecular hydrogen bonding. Those attractions help explain temperature buffering; an absence of attractions does not. Fix: Mark water’s partially positive and partially negative regions before identifying intermolecular attractions."],["D","Water’s low specific heat capacity allows it to absorb substantial energy while undergoing only a small temperature increase.",false,"Specific-heat reversal: Low specific heat capacity means relatively little energy raises the temperature of a given mass. Substantial energy absorption with little warming instead indicates high specific heat capacity. Fix: Compare the energy required to warm equal masses by the same temperature increment."]]},{"k":"APBIO-MCQ-102","t":"Structure of Water and Hydrogen Bonding","s":"A researcher adds equal amounts of heat to equal masses of water and liquid X during each heating interval. Neither liquid evaporates, and no heat escapes to the surroundings.\n\nTemperature data:\nHeating intervals completed | Water (°C) | Liquid X (°C)\n0 | 20 | 20\n1 | 21 | 25\n2 | 22 | 30\n\nWhich statement best describes the temperature pattern and explains the molecular basis of water's response?","a":"C","c":[["A","Water shows a larger temperature increase, indicating a lower specific heat capacity than liquid X.",false,"Comparison reversal: Water's temperature increases by 2°C, not 10°C. Its smaller increase under equal heating and equal mass indicates a higher specific heat capacity than liquid X. Fix: Subtract each liquid's initial temperature from its final temperature before comparing increases."],["B","Water shows a smaller temperature increase because added energy breaks covalent bonds between its oxygen and hydrogen atoms.",false,"Bond-type confusion: This explanation substitutes bonds within water molecules for attractions between molecules. Water's high specific heat capacity involves disruption of intermolecular hydrogen bonds, not breaking its O–H covalent bonds. Fix: Identify whether the bonds in your explanation connect separate molecules or atoms within one molecule."],["C","Water shows a smaller temperature increase because some added energy disrupts hydrogen bonds between its polar molecules.",true,"Water warms by 2°C while liquid X warms by 10°C under equal heating. Water's polarity enables hydrogen bonding, and disrupting these attractions absorbs energy, contributing to its high specific heat capacity. This property helps stabilize temperatures in organisms and aquatic environments."],["D","Water shows a smaller temperature increase because its nonpolar molecules do not form hydrogen bonds.",false,"Neutral-means-nonpolar misconception: Water has no net charge, but its charge distribution is uneven, making it polar. Its molecules form hydrogen bonds; the absence of these attractions does not explain its high specific heat capacity. Fix: Check charge distribution within a molecule rather than using net charge to determine polarity."]]},{"k":"APBIO-MCQ-SV-102-v1","t":"Structure of Water and Hydrogen Bonding","s":"Equal masses of water and liquid Y start at the same temperature inside a sealed chamber. Each liquid loses the same amount of heat to the chamber during every 2-minute period, and neither liquid freezes or evaporates. Temperature data: Time (min) | Water (°C) | Liquid Y (°C) — 0 | 40.0 | 40.0; 2 | 38.5 | 34.0; 4 | 37.0 | 28.0. Which statement best describes the cooling pattern and explains the molecular basis of water's response?","a":"A","c":[["A","Water's temperature falls less than liquid Y's because hydrogen bonds forming between its polar molecules release energy as it cools.",true,"Water drops 3.0°C while liquid Y drops 12.0°C after equal heat loss from equal masses. Water's polarity allows hydrogen bonds to form as it cools, and forming these bonds releases energy that offsets the loss. This high specific heat capacity helps keep organisms and aquatic habitats at stable temperatures."],["B","Water's temperature falls more than liquid Y's, showing that water has a lower specific heat capacity.",false,"Comparison reversal: the student misreads which liquid changed more. Water falls only 3.0°C versus 12.0°C for liquid Y, so water has the higher specific heat capacity. Fix: Subtract each liquid's final temperature from its starting temperature before comparing changes."],["C","Water's temperature falls less than liquid Y's because new covalent bonds form between its oxygen and hydrogen atoms as it cools.",false,"Bond-type confusion: the student swaps bonds within a molecule for attractions between molecules. Water's O–H covalent bonds stay intact during cooling; the energy released comes from hydrogen bonds forming between separate water molecules. Fix: Ask whether each bond you cite joins atoms within one molecule or links separate molecules."],["D","Water's temperature falls less than liquid Y's because its nonpolar molecules cannot form hydrogen bonds.",false,"Neutral-means-nonpolar misconception: the student assumes a molecule with no net charge must be nonpolar. Water's electrons are shared unevenly, giving it partial charges and allowing hydrogen bonds, which are what slow its temperature change. Fix: Check how charge is distributed within the molecule instead of relying on its net charge."]]},{"k":"APBIO-MCQ-SV-102-v2","t":"Structure of Water and Hydrogen Bonding","s":"A wildlife center compares two liquids for use in a temperature buffer for an animal enclosure. Equal masses of water and liquid R are warmed from 18°C. The table records the heat absorbed to reach each temperature; no heat escapes, and neither liquid changes phase.\n\nTemperature reached (°C) | Heat absorbed by water (kJ) | Heat absorbed by liquid R (kJ)\n18 | 0 | 0\n21 | 12 | 3\n24 | 24 | 6\n\nWhich statement best describes the data and explains water’s thermal behavior?","a":"B","c":[["A","Water requires less heat for the same temperature increase, indicating a lower specific heat capacity than liquid R.",false,"Comparison reversal: The table shows water absorbing four times as much heat as liquid R for the same warming. With equal masses, greater heat absorbed per degree indicates higher, not lower, specific heat capacity. Fix: Compare the heat values within one temperature row before identifying the higher specific heat capacity."],["B","Water requires more heat for the same temperature increase because some absorbed energy disrupts hydrogen bonds between its polar molecules.",true,"For a 6°C increase, water absorbs 24 kJ while liquid R absorbs 6 kJ, indicating water’s higher specific heat capacity. Water’s polarity enables intermolecular hydrogen bonding, whose disruption absorbs energy. This resistance to temperature change helps stabilize biological temperatures."],["C","Water requires more heat for the same temperature increase because absorbed energy breaks covalent bonds within its molecules.",false,"Bond-type confusion: Ordinary warming does not break the covalent bonds joining oxygen and hydrogen within water molecules. The relevant energy absorption involves disrupting hydrogen bonds between separate molecules. Fix: Locate each proposed bond within a molecule or between separate molecules."],["D","Water requires more heat for the same temperature increase because its electrically neutral molecules are nonpolar and cannot form hydrogen bonds.",false,"Neutral-means-nonpolar misconception: Having no net charge does not make water nonpolar; its charge distribution is uneven. Hydrogen bonding between its polar molecules contributes to its high specific heat capacity. Fix: Check whether charge is distributed evenly rather than relying on the molecule’s net charge."]]},{"k":"APBIO-MCQ-SV-102-v3","t":"Structure of Water and Hydrogen Bonding","s":"At a desert field station, equal masses of water and liquid Z sit side by side in sealed, identical containers. During the day both containers absorb the same amount of solar heat, and at night both lose the same amount of heat. Neither liquid evaporates or changes phase.\n\nTemperature data:\nTime of day | Water (°C) | Liquid Z (°C)\n6:00 | 15 | 8\n12:00 | 18 | 20\n18:00 | 19 | 26\n24:00 | 16 | 12\n\nWhich statement best describes the pattern in the data and explains the molecular basis of water's response?","a":"A","c":[["A","Water's temperature varies over a narrower range because energy gained or lost goes partly into breaking or forming hydrogen bonds between its polar molecules.",true,"Water spans 4°C (15 to 19) while liquid Z spans 18°C (8 to 26) under equal heat exchange. Water's polarity enables hydrogen bonding, and breaking or forming these bonds absorbs or releases energy, giving water a high specific heat capacity that buffers organisms against temperature swings."],["B","Water's temperature varies over a wider range, showing that water has a lower specific heat capacity than liquid Z.",false,"Comparison reversal: the student misreads which liquid changed more. Water's range is only 4°C versus 18°C for liquid Z, so water has the higher specific heat capacity. Fix: Compute maximum minus minimum temperature for each liquid before comparing."],["C","Water's temperature varies over a narrower range because absorbed heat breaks the covalent bonds between oxygen and hydrogen atoms within each water molecule.",false,"Bond-type confusion: this mistakes bonds inside a molecule for attractions between molecules. Daily heating does not split water's O–H covalent bonds; the energy disrupts intermolecular hydrogen bonds. Fix: Ask whether the bond you cite joins atoms within one molecule or links separate molecules."],["D","Water's temperature varies over a narrower range because its molecules are nonpolar and therefore do not form hydrogen bonds.",false,"Neutral-means-nonpolar misconception: water has no net charge, but its electrons are shared unevenly, so it is polar. Its molecules do hydrogen bond, and that bonding, not its absence, explains the temperature buffering. Fix: Check how charge is distributed within the molecule instead of relying on net charge."]]},{"k":"APBIO-MCQ-103","t":"Structure of Water and Hydrogen Bonding","s":"A researcher models an organism’s temperature regulation using water and a hypothetical replacement liquid. The replacement molecules are less polar and form weaker hydrogen bonds than water molecules. In one trial, equal masses absorb equal amounts of thermal energy without evaporating. In a second trial, equal masses evaporate, drawing all required energy from the model organism. Considering the effects of weaker hydrogen bonding, which prediction about the replacement liquid is best supported?","a":"B","c":[["A","It undergoes a smaller temperature increase in the first trial and removes less energy from the organism in the second trial.",false,"Reversed heat-capacity effect: this prediction treats weaker hydrogen bonding as increased resistance to temperature change. Weaker interactions require less energy to disrupt, reducing specific heat capacity rather than increasing it. Fix: Compare temperature changes for equal energy inputs when specific heat capacity decreases."],["B","It undergoes a larger temperature increase in the first trial and removes less energy from the organism in the second trial.",true,"Reduced polarity weakens intermolecular hydrogen bonding, so less energy is needed to disrupt these interactions. This lowers specific heat capacity and heat of vaporization: equal energy input produces greater warming, while evaporation of an equal mass removes less energy."],["C","It undergoes a larger temperature increase in the first trial and removes more energy from the organism in the second trial.",false,"Evaporation ease–cooling confusion: easier evaporation does not mean more energy is removed per unit mass. Weaker hydrogen bonds lower the energy required for an equal mass to evaporate. Fix: Separate how easily evaporation occurs from the energy absorbed per gram evaporated."],["D","It undergoes a smaller temperature increase in the first trial and removes more energy from the organism in the second trial.",false,"Bond-strength–energy reversal: this prediction assigns stronger thermal buffering and greater evaporative cooling to weaker hydrogen bonds. Both effects depend on the energy needed to disrupt intermolecular interactions, which decreases as those interactions weaken. Fix: Trace weaker hydrogen bonds to lower energy requirements before predicting each thermal effect."]]},{"k":"APBIO-MCQ-SV-103-v1","t":"Structure of Water and Hydrogen Bonding","s":"At a bird hatchery, liquid-filled trays help stabilize egg temperatures, while evaporation from separate wet pads removes heat from the eggs. A proposed synthetic fluid has less polar molecules and weaker intermolecular hydrogen bonds than water. Assume these weaker interactions reduce both its specific heat capacity and its heat of vaporization. Compared with water, how much energy would an equal mass of this fluid require to warm by 2°C without evaporating, and what mass would need to evaporate to remove the same amount of heat from the eggs? Assume all energy for evaporation comes from the eggs.","a":"B","c":[["A","Warming would require more energy, and cooling would require a larger mass to evaporate.",false,"Reversed heat-capacity effect: this prediction incorrectly associates weaker hydrogen bonding with greater resistance to warming. Lower specific heat capacity means less energy is required for an equal mass to undergo the same temperature increase. Fix: Hold mass and temperature increase constant, then compare the energy required for warming."],["B","Warming would require less energy, and cooling would require a larger mass to evaporate.",true,"Reduced polarity weakens hydrogen bonding, lowering the energy needed for warming and evaporation per gram. Thus, an equal mass needs less energy for the same temperature increase, but removing a fixed amount of heat requires more grams to evaporate."],["C","Warming would require less energy, and cooling would require a smaller mass to evaporate.",false,"Evaporation ease–cooling confusion: easier evaporation is mistaken for greater heat removal per gram. Weaker hydrogen bonds reduce the energy absorbed per gram evaporated, so a smaller evaporated mass cannot provide the same cooling. Fix: Determine heat removed per gram before predicting the mass needed for equal cooling."],["D","Warming would require more energy, and cooling would require a smaller mass to evaporate.",false,"Bond-strength–energy reversal: this prediction assigns greater thermal buffering and greater cooling per gram to weaker hydrogen bonds. Weaker interactions instead lower both the energy required for warming and the energy absorbed during evaporation per gram. Fix: Trace each reduced energy requirement separately to the requested energy or mass."]]}]$pl$::jsonb; r jsonb; c jsonb; v_ci uuid; v_civ uuid; n int;
begin
  if jsonb_array_length(p) <> 10 then raise exception 'chunk size'; end if;
  if exists (select 1 from app.content_items ci where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x))
    then raise exception 'chunk already loaded'; end if;
  for r in select * from jsonb_array_elements(p) loop
    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values ('2d88ba5e-a6a3-43b8-bfae-9e5505a178a7', r->>'k', 'mcq', r->>'t', 'draft') returning id into v_ci;
    insert into app.content_item_versions (content_item_id, version_num, stem, stimulus, content_hash, status, review_status, canonical_answer_1)
    values (v_ci, 1, r->>'s', null, md5(r->>'k'), 'draft', 'tutor_review_pending', r->>'a') returning id into v_civ;
    for c in select * from jsonb_array_elements(r->'c') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>0, c->>1, (c->>2)::boolean, c->>3);
    end loop;
  end loop;
  select count(*) into n from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.mcq_choices m on m.content_item_version_id=v.id
   where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.status='draft' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x);
  if n <> 40 then raise exception 'chunk 1: expected 40 choice rows, got %', n; end if;
  raise notice 'chunk 1: loaded 10 draft items';
end
$do$;
